import { Tab, TabList, TabPanel, Tabs } from "@fantappero/ui";
import { useAuth } from "../auth/AuthContext";
import { RequirePermissions } from "../auth/RequirePermissions";
import { useLocation, useNavigate } from "../router/simpleRouter";
import { LeagueAdminPage } from "./LeagueAdminPage";
import { LeagueHomePage } from "./LeagueHomePage";

const TABS = [
  { value: "league-home", label: "Home lega", path: "/lega/home", permission: "league:view" as const },
  {
    value: "league-admin",
    label: "Amministrazione lega",
    path: "/lega/amministrazione",
    permission: "league:admin" as const,
  },
];

/**
 * Home lega/Amministrazione riunite in un'unica pagina a tab (EP13-P01).
 * Scegliere/creare/unirsi a una lega è ora nell'header, sempre visibile.
 */
export function LeagueHubPage() {
  const { pathname } = useLocation();
  const navigate = useNavigate();
  const { can } = useAuth();
  const activeTab = TABS.find((tab) => tab.path === pathname)?.value ?? "league-home";
  const visibleTabs = TABS.filter((tab) => can([tab.permission]));

  return (
    <Tabs
      value={activeTab}
      onValueChange={(value) => {
        const target = TABS.find((tab) => tab.value === value);
        if (target) navigate(target.path);
      }}
      aria-label="Lega"
    >
      {visibleTabs.length > 1 ? (
        <TabList>
          {visibleTabs.map((tab) => (
            <Tab key={tab.value} value={tab.value}>
              {tab.label}
            </Tab>
          ))}
        </TabList>
      ) : null}
      <TabPanel value="league-home">
        <RequirePermissions required={["league:view"]}>
          <LeagueHomePage />
        </RequirePermissions>
      </TabPanel>
      <TabPanel value="league-admin">
        <RequirePermissions required={["league:admin"]}>
          <LeagueAdminPage />
        </RequirePermissions>
      </TabPanel>
    </Tabs>
  );
}

import { Tab, TabList, TabPanel, Tabs } from "@fantappero/ui";
import { useEffect } from "react";
import { useAuth } from "../auth/AuthContext";
import { RequirePermissions } from "../auth/RequirePermissions";
import { useLocation, useNavigate } from "../router/simpleRouter";
import { LeagueAdminPage } from "./LeagueAdminPage";
import { LeagueHomePage } from "./LeagueHomePage";

const TABS = [
  { value: "league-home", label: "Home lega", path: "/lega/home", permission: "league:view" as const },
  {
    value: "league-admin",
    label: "Amministrazione lega",
    path: "/lega/amministrazione",
    permission: "league:admin" as const,
  },
];

/**
 * Home lega/Amministrazione riunite in un'unica pagina a tab (EP13-P01).
 * Scegliere/creare/unirsi a una lega è ora nell'header, sempre visibile.
 *
 * Per evitare contenuti duplicati (EP13-P02), i due tab non sono più mostrati
 * entrambi allo stesso utente: chi ha `league:admin` vede solo Amministrazione
 * (che include già stato lega, regolamento e partecipanti), gli altri membri
 * vedono solo Home lega. Un admin che atterra su /lega/home (link vecchi,
 * preferiti…) viene reindirizzato in automatico su Amministrazione.
 */
export function LeagueHubPage() {
  const { pathname } = useLocation();
  const navigate = useNavigate();
  const { can } = useAuth();
  const isAdmin = can(["league:admin"]);
  const visibleTabs = isAdmin
    ? TABS.filter((tab) => tab.value === "league-admin")
    : TABS.filter((tab) => tab.value === "league-home" && can([tab.permission]));

  const requestedTab = TABS.find((tab) => tab.path === pathname)?.value ?? "league-home";
  const activeTab = isAdmin && requestedTab === "league-home" ? "league-admin" : requestedTab;

  useEffect(() => {
    const target = TABS.find((tab) => tab.value === activeTab);
    if (target && target.path !== pathname) {
      navigate(target.path, { replace: true });
    }
  }, [activeTab, pathname, navigate]);

  return (
    <Tabs
      value={activeTab}
      onValueChange={(value) => {
        const target = TABS.find((tab) => tab.value === value);
        if (target) navigate(target.path);
      }}
      aria-label="Lega"
    >
      {visibleTabs.length > 1 ? (
        <TabList>
          {visibleTabs.map((tab) => (
            <Tab key={tab.value} value={tab.value}>
              {tab.label}
            </Tab>
          ))}
        </TabList>
      ) : null}
      <TabPanel value="league-home">
        <RequirePermissions required={["league:view"]}>
          <LeagueHomePage />
        </RequirePermissions>
      </TabPanel>
      <TabPanel value="league-admin">
        <RequirePermissions required={["league:admin"]}>
          <LeagueAdminPage />
        </RequirePermissions>
      </TabPanel>
    </Tabs>
  );
}

import type { LeagueMember } from "@fantappero/contracts";
import { Button, UiStatePanel } from "@fantappero/ui";
import { useCallback, useEffect, useState } from "react";
import {
  assignRandomAiRoster,
  ensureFantasyTeams,
  fetchLeagueMembers,
  removeLeagueMember,
  transferLeagueAdmin,
} from "../api/leagues";
import { getApiErrorMessage } from "../auth/AuthContext";
import { loadStoredSession } from "../auth/sessionStorage";

const DEMO_MEMBERS: LeagueMember[] = [
  {
    userId: "demo-admin",
    displayName: "Marco",
    userType: "human",
    role: "league_admin",
    joinedAt: "2026-08-01T10:00:00Z",
  },
  {
    userId: "demo-member-1",
    displayName: "Giulia",
    userType: "human",
    role: "member",
    joinedAt: "2026-08-02T10:00:00Z",
  },
  {
    userId: "demo-member-2",
    displayName: "Allenatore IA 01",
    userType: "ai",
    role: "member",
    joinedAt: "2026-08-03T10:00:00Z",
  },
];

type LeagueMembersPanelProps = {
  leagueId: string | null;
  isDemoMode: boolean;
  search: string;
};

export function LeagueMembersPanel({
  leagueId,
  isDemoMode,
  search,
}: LeagueMembersPanelProps) {
  const demoState = new URLSearchParams(search).get("partecipanti");
  const [members, setMembers] = useState<LeagueMember[]>(
    isDemoMode && demoState !== "empty" ? DEMO_MEMBERS : [],
  );
  const [loading, setLoading] = useState(!isDemoMode || demoState === "loading");
  const [error, setError] = useState<string | null>(
    isDemoMode && demoState === "error"
      ? "Impossibile caricare i partecipanti (demo)."
      : null,
  );
  const [success, setSuccess] = useState<string | null>(null);
  const [workingId, setWorkingId] = useState<string | null>(null);

  const loadMembers = useCallback(async () => {
    setSuccess(null);
    if (isDemoMode) {
      setLoading(demoState === "loading");
      setError(
        demoState === "error" ? "Impossibile caricare i partecipanti (demo)." : null,
      );
      setMembers(demoState === "empty" || demoState === "error" ? [] : DEMO_MEMBERS);
      return;
    }
    if (!leagueId) {
      setLoading(false);
      setMembers([]);
      return;
    }
    const session = loadStoredSession();
    if (!session?.accessToken) {
      setLoading(false);
      setError("Sessione non disponibile. Accedi di nuovo.");
      return;
    }
    setLoading(true);
    setError(null);
    try {
      setMembers(await fetchLeagueMembers(session.accessToken, leagueId));
    } catch (loadError) {
      setMembers([]);
      setError(getApiErrorMessage(loadError, "Impossibile caricare i partecipanti."));
    } finally {
      setLoading(false);
    }
  }, [demoState, isDemoMode, leagueId]);

  useEffect(() => {
    void loadMembers();
  }, [loadMembers]);

  async function onTransfer(target: LeagueMember) {
    setError(null);
    setSuccess(null);
    if (isDemoMode) {
      setMembers((current) =>
        current.map((member) => ({
          ...member,
          role: member.userId === target.userId ? "league_admin" : "member",
        })),
      );
      setSuccess(`Ruolo di amministratore trasferito a ${target.displayName}.`);
      return;
    }
    const session = loadStoredSession();
    if (!leagueId || !session?.accessToken) {
      setError("Sessione non disponibile. Accedi di nuovo.");
      return;
    }
    setWorkingId(`transfer-${target.userId}`);
    try {
      const transferred = await transferLeagueAdmin(
        session.accessToken,
        leagueId,
        target.userId,
      );
      setMembers((current) =>
        current.map((member) => ({
          ...member,
          role: member.userId === transferred.userId ? "league_admin" : "member",
        })),
      );
      setSuccess(`Ruolo di amministratore trasferito a ${transferred.displayName}.`);
    } catch (transferError) {
      setError(getApiErrorMessage(transferError, "Impossibile trasferire il ruolo."));
    } finally {
      setWorkingId(null);
    }
  }

  async function onRemove(target: LeagueMember) {
    setError(null);
    setSuccess(null);
    if (isDemoMode) {
      setMembers((current) => current.filter((member) => member.userId !== target.userId));
      setSuccess(`${target.displayName} è stato rimosso dalla lega.`);
      return;
    }
    const session = loadStoredSession();
    if (!leagueId || !session?.accessToken) {
      setError("Sessione non disponibile. Accedi di nuovo.");
      return;
    }
    setWorkingId(`remove-${target.userId}`);
    try {
      const removed = await removeLeagueMember(session.accessToken, leagueId, target.userId);
      setMembers((current) => current.filter((member) => member.userId !== removed.userId));
      setSuccess(`${removed.displayName} è stato rimosso dalla lega.`);
    } catch (removeError) {
      setError(getApiErrorMessage(removeError, "Impossibile rimuovere il partecipante."));
    } finally {
      setWorkingId(null);
    }
  }

  async function onAssignRandomRoster(target: LeagueMember) {
    setError(null);
    setSuccess(null);
    if (target.userType !== "ai") {
      setError("La rosa random è disponibile solo per i fantallenatori IA.");
      return;
    }
    if (isDemoMode) {
      setSuccess(`Rosa random assegnata a ${target.displayName} (demo).`);
      return;
    }
    const session = loadStoredSession();
    if (!leagueId || !session?.accessToken) {
      setError("Sessione non disponibile. Accedi di nuovo.");
      return;
    }
    setWorkingId(`random-${target.userId}`);
    try {
      const ensured = await ensureFantasyTeams(session.accessToken, leagueId);
      const team = ensured.teams.find((row) => row.userId === target.userId);
      if (!team) {
        setError("Squadra del fantallenatore IA non trovata. Assicura prima le squadre.");
        return;
      }
      const updated = await assignRandomAiRoster(session.accessToken, leagueId, team.id);
      setSuccess(
        `Rosa random assegnata a ${target.displayName}: ${updated.filledSlots}/${updated.rosterSize} giocatori.`,
      );
    } catch (assignError) {
      setError(
        getApiErrorMessage(assignError, "Impossibile assegnare la rosa random."),
      );
    } finally {
      setWorkingId(null);
    }
  }

  return (
    <section className="fa-members" aria-labelledby="league-members-title">
      <h2 id="league-members-title">Partecipanti iscritti</h2>
      <p>Trasferisci il ruolo admin o rimuovi un partecipante prima dell’avvio.</p>

      {loading ? (
        <UiStatePanel
          state="loading"
          title="Caricamento partecipanti"
          message="Recupero dei membri della lega in corso…"
          testId="league-members-loading"
        />
      ) : null}
      {!loading && error ? (
        <div>
          <UiStatePanel
            state="error"
            title="Partecipanti non disponibili"
            message={error}
            testId="league-members-error"
          />
          <Button type="button" variant="ghost" onClick={() => void loadMembers()}>
            Riprova
          </Button>
        </div>
      ) : null}
      {!loading && !error && members.length === 0 ? (
        <UiStatePanel
          state="empty"
          title="Nessun partecipante"
          message="Non risultano partecipanti iscritti alla lega."
          testId="league-members-empty"
        />
      ) : null}
      {!loading && !error && members.length > 0 ? (
        <ul className="fa-member-list" data-testid="league-members-list">
          {members.map((member) => (
            <li key={member.userId} className="fa-member-list__item">
              <span>
                <strong>{member.displayName}</strong>
                {` · ${member.role === "league_admin" ? "Amministratore" : "Partecipante"}`}
                {member.userType === "ai" ? " · IA" : ""}
              </span>
              {member.role === "member" ? (
                <span className="fa-ds-showcase__row">
                  {member.userType === "ai" ? (
                    <Button
                      type="button"
                      variant="secondary"
                      size="sm"
                      data-testid={`league-members-random-ai-${member.userId}`}
                      loading={workingId === `random-${member.userId}`}
                      disabled={workingId !== null}
                      onClick={() => void onAssignRandomRoster(member)}
                    >
                      Assegna rosa random
                    </Button>
                  ) : null}
                  <Button
                    type="button"
                    variant="secondary"
                    size="sm"
                    loading={workingId === `transfer-${member.userId}`}
                    disabled={workingId !== null}
                    onClick={() => void onTransfer(member)}
                  >
                    Trasferisci admin
                  </Button>
                  <Button
                    type="button"
                    variant="danger"
                    size="sm"
                    loading={workingId === `remove-${member.userId}`}
                    disabled={workingId !== null}
                    onClick={() => void onRemove(member)}
                  >
                    Rimuovi
                  </Button>
                </span>
              ) : null}
            </li>
          ))}
        </ul>
      ) : null}
      {success ? (
        <UiStatePanel
          state="success"
          title="Partecipanti aggiornati"
          message={success}
          testId="league-members-success"
        />
      ) : null}
    </section>
  );
}

import type { LeagueMember } from "@fantappero/contracts";
import { Button, UiStatePanel } from "@fantappero/ui";
import { useCallback, useEffect, useState } from "react";
import {
  assignRandomAiRoster,
  ensureFantasyTeams,
  fetchLeagueMembers,
  removeLeagueMember,
  transferLeagueAdmin,
} from "../api/leagues";
import { getApiErrorMessage } from "../auth/AuthContext";
import { loadStoredSession } from "../auth/sessionStorage";

const DEMO_MEMBERS: LeagueMember[] = [
  {
    userId: "demo-admin",
    displayName: "Marco",
    userType: "human",
    role: "league_admin",
    joinedAt: "2026-08-01T10:00:00Z",
  },
  {
    userId: "demo-member-1",
    displayName: "Giulia",
    userType: "human",
    role: "member",
    joinedAt: "2026-08-02T10:00:00Z",
  },
  {
    userId: "demo-member-2",
    displayName: "Allenatore IA 01",
    userType: "ai",
    role: "member",
    joinedAt: "2026-08-03T10:00:00Z",
  },
];

type LeagueMembersPanelProps = {
  leagueId: string | null;
  isDemoMode: boolean;
  search: string;
};

export function LeagueMembersPanel({
  leagueId,
  isDemoMode,
  search,
}: LeagueMembersPanelProps) {
  const demoState = new URLSearchParams(search).get("partecipanti");
  const [members, setMembers] = useState<LeagueMember[]>(
    isDemoMode && demoState !== "empty" ? DEMO_MEMBERS : [],
  );
  const [loading, setLoading] = useState(!isDemoMode || demoState === "loading");
  const [error, setError] = useState<string | null>(
    isDemoMode && demoState === "error"
      ? "Impossibile caricare i partecipanti (demo)."
      : null,
  );
  const [success, setSuccess] = useState<string | null>(null);
  const [workingId, setWorkingId] = useState<string | null>(null);

  const loadMembers = useCallback(async () => {
    setSuccess(null);
    if (isDemoMode) {
      setLoading(demoState === "loading");
      setError(
        demoState === "error" ? "Impossibile caricare i partecipanti (demo)." : null,
      );
      setMembers(demoState === "empty" || demoState === "error" ? [] : DEMO_MEMBERS);
      return;
    }
    if (!leagueId) {
      setLoading(false);
      setMembers([]);
      return;
    }
    const session = loadStoredSession();
    if (!session?.accessToken) {
      setLoading(false);
      setError("Sessione non disponibile. Accedi di nuovo.");
      return;
    }
    setLoading(true);
    setError(null);
    try {
      setMembers(await fetchLeagueMembers(session.accessToken, leagueId));
    } catch (loadError) {
      setMembers([]);
      setError(getApiErrorMessage(loadError, "Impossibile caricare i partecipanti."));
    } finally {
      setLoading(false);
    }
  }, [demoState, isDemoMode, leagueId]);

  useEffect(() => {
    void loadMembers();
  }, [loadMembers]);

  async function onTransfer(target: LeagueMember) {
    setError(null);
    setSuccess(null);
    if (isDemoMode) {
      setMembers((current) =>
        current.map((member) => ({
          ...member,
          role: member.userId === target.userId ? "league_admin" : "member",
        })),
      );
      setSuccess(`Ruolo di amministratore trasferito a ${target.displayName}.`);
      return;
    }
    const session = loadStoredSession();
    if (!leagueId || !session?.accessToken) {
      setError("Sessione non disponibile. Accedi di nuovo.");
      return;
    }
    setWorkingId(`transfer-${target.userId}`);
    try {
      const transferred = await transferLeagueAdmin(
        session.accessToken,
        leagueId,
        target.userId,
      );
      setMembers((current) =>
        current.map((member) => ({
          ...member,
          role: member.userId === transferred.userId ? "league_admin" : "member",
        })),
      );
      setSuccess(`Ruolo di amministratore trasferito a ${transferred.displayName}.`);
    } catch (transferError) {
      setError(getApiErrorMessage(transferError, "Impossibile trasferire il ruolo."));
    } finally {
      setWorkingId(null);
    }
  }

  async function onRemove(target: LeagueMember) {
    setError(null);
    setSuccess(null);
    if (isDemoMode) {
      setMembers((current) => current.filter((member) => member.userId !== target.userId));
      setSuccess(`${target.displayName} è stato rimosso dalla lega.`);
      return;
    }
    const session = loadStoredSession();
    if (!leagueId || !session?.accessToken) {
      setError("Sessione non disponibile. Accedi di nuovo.");
      return;
    }
    setWorkingId(`remove-${target.userId}`);
    try {
      const removed = await removeLeagueMember(session.accessToken, leagueId, target.userId);
      setMembers((current) => current.filter((member) => member.userId !== removed.userId));
      setSuccess(`${removed.displayName} è stato rimosso dalla lega.`);
    } catch (removeError) {
      setError(getApiErrorMessage(removeError, "Impossibile rimuovere il partecipante."));
    } finally {
      setWorkingId(null);
    }
  }

  async function onAssignRandomRoster(target: LeagueMember) {
    setError(null);
    setSuccess(null);
    if (target.userType !== "ai") {
      setError("La rosa random è disponibile solo per i fantallenatori IA.");
      return;
    }
    if (isDemoMode) {
      setSuccess(`Rosa random assegnata a ${target.displayName} (demo).`);
      return;
    }
    const session = loadStoredSession();
    if (!leagueId || !session?.accessToken) {
      setError("Sessione non disponibile. Accedi di nuovo.");
      return;
    }
    setWorkingId(`random-${target.userId}`);
    try {
      const ensured = await ensureFantasyTeams(session.accessToken, leagueId);
      const team = ensured.teams.find((row) => row.userId === target.userId);
      if (!team) {
        setError("Squadra del fantallenatore IA non trovata. Assicura prima le squadre.");
        return;
      }
      const updated = await assignRandomAiRoster(session.accessToken, leagueId, team.id);
      setSuccess(
        `Rosa random assegnata a ${target.displayName}: ${updated.filledSlots}/${updated.rosterSize} giocatori.`,
      );
    } catch (assignError) {
      setError(
        getApiErrorMessage(assignError, "Impossibile assegnare la rosa random."),
      );
    } finally {
      setWorkingId(null);
    }
  }

  return (
    <section
      className="fa-members"
      aria-labelledby="league-members-title"
      data-testid="league-members-panel"
    >
      <h2 id="league-members-title">Partecipanti iscritti</h2>
      <p>Trasferisci il ruolo admin o rimuovi un partecipante prima dell’avvio.</p>

      {loading ? (
        <UiStatePanel
          state="loading"
          title="Caricamento partecipanti"
          message="Recupero dei membri della lega in corso…"
          testId="league-members-loading"
        />
      ) : null}
      {!loading && error ? (
        <div>
          <UiStatePanel
            state="error"
            title="Partecipanti non disponibili"
            message={error}
            testId="league-members-error"
          />
          <Button type="button" variant="ghost" onClick={() => void loadMembers()}>
            Riprova
          </Button>
        </div>
      ) : null}
      {!loading && !error && members.length === 0 ? (
        <UiStatePanel
          state="empty"
          title="Nessun partecipante"
          message="Non risultano partecipanti iscritti alla lega."
          testId="league-members-empty"
        />
      ) : null}
      {!loading && !error && members.length > 0 ? (
        <ul className="fa-member-list" data-testid="league-members-list">
          {members.map((member) => (
            <li key={member.userId} className="fa-member-list__item">
              <span>
                <strong>{member.displayName}</strong>
                {` · ${member.role === "league_admin" ? "Amministratore" : "Partecipante"}`}
                {member.userType === "ai" ? " · IA" : ""}
              </span>
              {member.role === "member" ? (
                <span className="fa-ds-showcase__row">
                  {member.userType === "ai" ? (
                    <Button
                      type="button"
                      variant="secondary"
                      size="sm"
                      data-testid={`league-members-random-ai-${member.userId}`}
                      loading={workingId === `random-${member.userId}`}
                      disabled={workingId !== null}
                      onClick={() => void onAssignRandomRoster(member)}
                    >
                      Assegna rosa random
                    </Button>
                  ) : null}
                  <Button
                    type="button"
                    variant="secondary"
                    size="sm"
                    loading={workingId === `transfer-${member.userId}`}
                    disabled={workingId !== null}
                    onClick={() => void onTransfer(member)}
                  >
                    Trasferisci admin
                  </Button>
                  <Button
                    type="button"
                    variant="danger"
                    size="sm"
                    loading={workingId === `remove-${member.userId}`}
                    disabled={workingId !== null}
                    onClick={() => void onRemove(member)}
                  >
                    Rimuovi
                  </Button>
                </span>
              ) : null}
            </li>
          ))}
        </ul>
      ) : null}
      {success ? (
        <UiStatePanel
          state="success"
          title="Partecipanti aggiornati"
          message={success}
          testId="league-members-success"
        />
      ) : null}
    </section>
  );
}

import type { LeagueLifecycle, LeagueState } from "@fantappero/contracts";
import { Button, UiStatePanel } from "@fantappero/ui";
import { useState } from "react";
import { transitionLeagueState } from "../api/leagues";
import { getApiErrorMessage } from "../auth/AuthContext";
import { loadStoredSession } from "../auth/sessionStorage";

const STATE_LABELS: Record<LeagueState, string> = {
  draft: "Bozza",
  configuring: "Configurazione",
  auction: "Asta",
  active: "Attiva",
  concluded: "Conclusa",
  archived: "Archiviata",
};

const ACTION_LABELS: Record<LeagueState, string> = {
  draft: "Torna alla bozza",
  configuring: "Apri configurazione",
  auction: "Avvia asta",
  active: "Avvia stagione",
  concluded: "Concludi stagione",
  archived: "Archivia lega",
};

type Props = {
  leagueId: string | null;
  lifecycle: LeagueLifecycle;
  isDemoMode: boolean;
  search: string;
  onChange: (lifecycle: LeagueLifecycle) => void;
};

function requestedState(search: string): "loading" | "empty" | "error" | null {
  const value = new URLSearchParams(search).get("stagione");
  return value === "loading" || value === "empty" || value === "error" ? value : null;
}

export function LeagueSeasonPanel({
  leagueId,
  lifecycle,
  isDemoMode,
  search,
  onChange,
}: Props) {
  const demoState = isDemoMode ? requestedState(search) : null;
  const [working, setWorking] = useState<LeagueState | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);

  if (demoState === "loading") {
    return (
      <UiStatePanel
        state="loading"
        title="Caricamento stato stagione"
        message="Verifica dello stato e dei prerequisiti in corso…"
        testId="league-season-loading"
      />
    );
  }
  if (demoState === "error") {
    return (
      <UiStatePanel
        state="error"
        title="Stato stagione non disponibile"
        message="Non è stato possibile verificare i prerequisiti (demo)."
        testId="league-season-error"
      />
    );
  }
  if (demoState === "empty") {
    return (
      <UiStatePanel
        state="empty"
        title="Nessuna transizione disponibile"
        message="La lega non ha azioni di stagione disponibili."
        testId="league-season-empty"
      />
    );
  }

  async function transition(targetState: LeagueState) {
    setError(null);
    setSuccess(null);
    if (isDemoMode) {
      onChange({ state: targetState, allowedTransitions: [], blockers: [] });
      setSuccess(`Stato aggiornato: ${STATE_LABELS[targetState]}.`);
      return;
    }
    if (!leagueId) {
      setError("Seleziona una lega prima di cambiarne lo stato.");
      return;
    }
    const stored = loadStoredSession();
    if (!stored?.accessToken) {
      setError("Sessione non disponibile. Accedi di nuovo.");
      return;
    }
    setWorking(targetState);
    try {
      const updated = await transitionLeagueState(stored.accessToken, leagueId, { targetState });
      onChange(updated);
      setSuccess(`Stato aggiornato: ${STATE_LABELS[updated.state]}.`);
    } catch (caught) {
      setError(getApiErrorMessage(caught, "Impossibile aggiornare lo stato della lega."));
    } finally {
      setWorking(null);
    }
  }

  return (
    <section className="fa-season-panel" data-testid="league-season-panel">
      <h2>Stato e avvio stagione</h2>
      <p>
        Stato corrente: <strong>{STATE_LABELS[lifecycle.state]}</strong>
      </p>

      {lifecycle.blockers.length > 0 ? (
        <div data-testid="league-season-blockers">
          <h3>Prerequisiti mancanti</h3>
          <ul>
            {lifecycle.blockers.map((blocker) => (
              <li key={blocker.code}>{blocker.message}</li>
            ))}
          </ul>
        </div>
      ) : null}

      {error ? (
        <UiStatePanel
          state="error"
          title="Stato non aggiornato"
          message={error}
          testId="league-season-transition-error"
        />
      ) : null}
      {success ? (
        <UiStatePanel
          state="success"
          title="Stato aggiornato"
          message={success}
          testId="league-season-transition-success"
        />
      ) : null}

      {lifecycle.allowedTransitions.length === 0 ? (
        <UiStatePanel
          state="empty"
          title="Nessuna transizione disponibile"
          message="Non ci sono ulteriori azioni disponibili per lo stato corrente."
          testId="league-season-no-transitions"
        />
      ) : (
        <div className="fa-ds-showcase__row">
          {lifecycle.allowedTransitions.map((targetState) => (
            <Button
              key={targetState}
              type="button"
              variant="primary"
              disabled={working !== null}
              onClick={() => void transition(targetState)}
              data-testid={`league-season-transition-${targetState}`}
            >
              {working === targetState ? "Aggiornamento…" : ACTION_LABELS[targetState]}
            </Button>
          ))}
        </div>
      )}
    </section>
  );
}

import type { LeagueLifecycle, LeagueState } from "@fantappero/contracts";
import {
  LEAGUE_LIFECYCLE_ACTION_HINT_LABEL,
  LEAGUE_LIFECYCLE_PHASES,
  describeLeagueLifecycleStep,
  leagueLifecyclePhaseIndex,
} from "@fantappero/contracts";
import { Badge, Button, UiStatePanel } from "@fantappero/ui";
import { useState } from "react";
import { transitionLeagueState } from "../api/leagues";
import { getApiErrorMessage } from "../auth/AuthContext";
import { loadStoredSession } from "../auth/sessionStorage";
import { leagueStateLabel } from "../leagues/leagueLabels";
import { useNavigate } from "../router/simpleRouter";

type Props = {
  leagueId: string | null;
  lifecycle: LeagueLifecycle;
  isDemoMode: boolean;
  search: string;
  onChange: (lifecycle: LeagueLifecycle) => void;
};

function requestedState(search: string): "loading" | "empty" | "error" | null {
  const value = new URLSearchParams(search).get("stagione");
  return value === "loading" || value === "empty" || value === "error" ? value : null;
}

// Selettore della sezione a cui rimandare l'admin per risolvere un blocker
// (EP03-05-UX). "teams" riusa la sezione Partecipanti: è lì che si assegnano
// le rose IA e si verificano i crediti, non esiste (ancora) un pannello dedicato.
// "calendar" non ha un anchor: la generazione/conferma calendario vive in
// Turni ▸ Calendario fantallenatori, quindi richiede una navigazione.
const ACTION_HINT_SELECTOR: Record<"rules" | "members" | "teams", string> = {
  rules: '[data-testid="league-admin-form"]',
  members: '[data-testid="league-members-panel"]',
  teams: '[data-testid="league-members-panel"]',
};

function scrollToActionHint(hint: "rules" | "members" | "teams") {
  document
    .querySelector(ACTION_HINT_SELECTOR[hint])
    ?.scrollIntoView({ behavior: "smooth", block: "start" });
}

export function LeagueSeasonPanel({
  leagueId,
  lifecycle,
  isDemoMode,
  search,
  onChange,
}: Props) {
  const demoState = isDemoMode ? requestedState(search) : null;
  const navigate = useNavigate();
  const [working, setWorking] = useState<LeagueState | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [confirmingRollback, setConfirmingRollback] = useState(false);

  if (demoState === "loading") {
    return (
      <UiStatePanel
        state="loading"
        title="Caricamento stato stagione"
        message="Verifica dello stato e dei prerequisiti in corso…"
        testId="league-season-loading"
      />
    );
  }
  if (demoState === "error") {
    return (
      <UiStatePanel
        state="error"
        title="Stato stagione non disponibile"
        message="Non è stato possibile verificare i prerequisiti (demo)."
        testId="league-season-error"
      />
    );
  }
  if (demoState === "empty") {
    return (
      <UiStatePanel
        state="empty"
        title="Nessuna transizione disponibile"
        message="La lega non ha azioni di stagione disponibili."
        testId="league-season-empty"
      />
    );
  }

  const step = describeLeagueLifecycleStep(lifecycle);
  const currentPhaseIndex = leagueLifecyclePhaseIndex(lifecycle.state);

  async function transition(targetState: LeagueState) {
    setError(null);
    setSuccess(null);
    setConfirmingRollback(false);
    if (isDemoMode) {
      onChange({ state: targetState, allowedTransitions: [], blockers: [] });
      setSuccess(`Stato aggiornato: ${leagueStateLabel(targetState)}.`);
      return;
    }
    if (!leagueId) {
      setError("Seleziona una lega prima di cambiarne lo stato.");
      return;
    }
    const stored = loadStoredSession();
    if (!stored?.accessToken) {
      setError("Sessione non disponibile. Accedi di nuovo.");
      return;
    }
    setWorking(targetState);
    try {
      const updated = await transitionLeagueState(stored.accessToken, leagueId, { targetState });
      onChange(updated);
      setSuccess(`Stato aggiornato: ${leagueStateLabel(updated.state)}.`);
    } catch (caught) {
      setError(getApiErrorMessage(caught, "Impossibile aggiornare lo stato della lega."));
    } finally {
      setWorking(null);
    }
  }

  return (
    <section className="fa-season-panel" data-testid="league-season-panel">
      <h2>Stato e avvio stagione</h2>

      <ol className="fa-lifecycle-stepper" data-testid="league-season-stepper">
        {LEAGUE_LIFECYCLE_PHASES.map((phase, index) => (
          <li
            key={phase.key}
            className={[
              "fa-lifecycle-step",
              index === currentPhaseIndex ? "fa-lifecycle-step--current" : "",
              index < currentPhaseIndex ? "fa-lifecycle-step--done" : "",
            ]
              .filter(Boolean)
              .join(" ")}
            aria-current={index === currentPhaseIndex ? "step" : undefined}
          >
            <span className="fa-lifecycle-step__index">{index + 1}</span>
            <span className="fa-lifecycle-step__label">{phase.label}</span>
          </li>
        ))}
      </ol>

      <p>
        Stato corrente: <strong>{leagueStateLabel(lifecycle.state)}</strong>
      </p>

      {lifecycle.blockers.length > 0 ? (
        <div className="fa-lifecycle-checklist" data-testid="league-season-blockers">
          <h3>Prerequisiti mancanti</h3>
          <ul>
            {lifecycle.blockers.map((blocker) => (
              <li key={blocker.code} className="fa-lifecycle-checklist__item">
                <Badge variant="warning">Da sistemare</Badge>
                <span className="fa-lifecycle-checklist__message">{blocker.message}</span>
                {blocker.actionHint ? (
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    onClick={() => {
                      if (blocker.actionHint === "calendar") {
                        navigate("/turni?tab=calendario");
                        return;
                      }
                      scrollToActionHint(blocker.actionHint!);
                    }}
                  >
                    {LEAGUE_LIFECYCLE_ACTION_HINT_LABEL[blocker.actionHint]} →
                  </Button>
                ) : null}
              </li>
            ))}
          </ul>
        </div>
      ) : null}

      {error ? (
        <UiStatePanel
          state="error"
          title="Stato non aggiornato"
          message={error}
          testId="league-season-transition-error"
        />
      ) : null}
      {success ? (
        <UiStatePanel
          state="success"
          title="Stato aggiornato"
          message={success}
          testId="league-season-transition-success"
        />
      ) : null}

      {step.forwardTarget === null ? (
        <UiStatePanel
          state="empty"
          title="Nessuna transizione disponibile"
          message="Non ci sono ulteriori azioni disponibili per lo stato corrente."
          testId="league-season-no-transitions"
        />
      ) : (
        <div className="fa-lifecycle-actions">
          <div className="fa-ds-showcase__row">
            <Button
              type="button"
              variant="primary"
              disabled={!step.forwardEnabled || working !== null}
              onClick={() => void transition(step.forwardTarget!)}
              data-testid="league-season-cta-forward"
            >
              {working === step.forwardTarget ? "Aggiornamento…" : step.forwardLabel}
            </Button>

            {step.rollbackTarget && !confirmingRollback ? (
              <Button
                type="button"
                variant="ghost"
                disabled={working !== null}
                onClick={() => setConfirmingRollback(true)}
                data-testid="league-season-cta-rollback"
              >
                {step.rollbackLabel}
              </Button>
            ) : null}
          </div>

          {step.rollbackTarget && confirmingRollback ? (
            <div className="fa-lifecycle-confirm" data-testid="league-season-rollback-confirm">
              <p>
                Sei sicuro? L&apos;asta in corso verrà interrotta e la lega tornerà in
                configurazione.
              </p>
              <div className="fa-ds-showcase__row">
                <Button
                  type="button"
                  variant="danger"
                  disabled={working !== null}
                  onClick={() => void transition(step.rollbackTarget!)}
                  data-testid="league-season-rollback-confirm-submit"
                >
                  {working === step.rollbackTarget ? "Aggiornamento…" : "Conferma"}
                </Button>
                <Button
                  type="button"
                  variant="ghost"
                  disabled={working !== null}
                  onClick={() => setConfirmingRollback(false)}
                >
                  Annulla
                </Button>
              </div>
            </div>
          ) : null}
        </div>
      )}
    </section>
  );
}

import type { LeagueSummary } from "@fantappero/contracts";
import {
  Breadcrumb,
  Button,
  Card,
  CardBody,
  CardHeader,
  PageContainer,
  UiStatePanel,
} from "@fantappero/ui";
import { useCallback, useEffect, useState } from "react";
import { fetchMyLeagues } from "../api/leagues";
import { getApiErrorMessage, useAuth } from "../auth/AuthContext";
import { loadStoredSession } from "../auth/sessionStorage";
import { Link, useLocation } from "../router/simpleRouter";
import { parseWireframeStateFromSearch } from "../wireframes/useWireframeState";

const DEMO_LEAGUES: LeagueSummary[] = [
  { id: "demo-league-1", name: "Lega Demo", role: "league_admin" },
];

function leagueStateLabel(state: string | undefined): string {
  if (state === "draft") {
    return "Bozza";
  }
  if (state === "active") {
    return "Attiva";
  }
  return "—";
}

/** Elenco leghe dell'utente con stato vuoto e azione di creazione (EP03-01). */
export function LeaguesPage() {
  const { isDemoMode } = useAuth();
  const { search } = useLocation();
  const demoState = isDemoMode ? parseWireframeStateFromSearch(search) : null;
  const [leagues, setLeagues] = useState<LeagueSummary[]>(() =>
    isDemoMode && demoState !== "empty" ? DEMO_LEAGUES : [],
  );
  const [loading, setLoading] = useState(() =>
    isDemoMode ? demoState === "loading" : true,
  );
  const [loadError, setLoadError] = useState<string | null>(() =>
    isDemoMode && demoState === "error" ? "Impossibile caricare le leghe (demo)." : null,
  );

  const loadLeagues = useCallback(async () => {
    if (isDemoMode) {
      if (demoState === "loading") {
        setLoading(true);
        setLoadError(null);
        setLeagues([]);
        return;
      }
      if (demoState === "error") {
        setLoading(false);
        setLoadError("Impossibile caricare le leghe (demo).");
        setLeagues([]);
        return;
      }
      if (demoState === "empty") {
        setLoading(false);
        setLoadError(null);
        setLeagues([]);
        return;
      }
      setLeagues(DEMO_LEAGUES);
      setLoading(false);
      return;
    }

    const stored = loadStoredSession();
    if (!stored?.accessToken) {
      setLoadError("Sessione non disponibile. Accedi di nuovo.");
      setLoading(false);
      return;
    }

    setLoading(true);
    setLoadError(null);
    try {
      const rows = await fetchMyLeagues(stored.accessToken);
      setLeagues(rows);
    } catch (error) {
      setLoadError(getApiErrorMessage(error, "Impossibile caricare le leghe."));
    } finally {
      setLoading(false);
    }
  }, [demoState, isDemoMode]);

  useEffect(() => {
    void loadLeagues();
  }, [loadLeagues]);

  return (
    <PageContainer
      title="Le tue leghe"
      header={<Breadcrumb items={[{ label: "Leghe" }]} />}
    >
      {loading ? (
        <UiStatePanel
          state="loading"
          title="Caricamento leghe"
          message="Recupero delle leghe in corso…"
          testId="leagues-loading"
        />
      ) : null}

      {!loading && loadError ? (
        <UiStatePanel
          state="error"
          title="Errore di caricamento"
          message={loadError}
          testId="leagues-error"
        />
      ) : null}

      {!loading && !loadError && leagues.length === 0 ? (
        <UiStatePanel
          state="empty"
          title="Nessuna lega"
          message="Non partecipi ancora a nessuna lega privata. Creane una per iniziare la configurazione."
          testId="leagues-empty"
        />
      ) : null}

      {!loading && !loadError && leagues.length > 0 ? (
        <section data-testid="leagues-list">
          <ul className="fa-league-list">
            {leagues.map((league) => (
              <li key={league.id} className="fa-league-list__item">
                <Card>
                  <CardHeader>{league.name}</CardHeader>
                  <CardBody>
                    <p>
                      Ruolo:{" "}
                      {league.role === "league_admin" ? "Amministratore" : "Partecipante"}
                    </p>
                    <p>Stato: {leagueStateLabel(undefined)}</p>
                  </CardBody>
                </Card>
              </li>
            ))}
          </ul>
        </section>
      ) : null}

      <div className="fa-ds-showcase__row" style={{ marginTop: "1rem" }}>
        <Link to="/leghe/crea">
          <Button variant="secondary" data-testid="leagues-create-link">
            Crea lega
          </Button>
        </Link>
        {!loading && loadError ? (
          <Button variant="ghost" onClick={() => void loadLeagues()} data-testid="leagues-retry">
            Ricarica
          </Button>
        ) : null}
      </div>
    </PageContainer>
  );
}

import type { LeagueSummary } from "@fantappero/contracts";
import {
  Breadcrumb,
  Button,
  Card,
  CardBody,
  CardHeader,
  PageContainer,
  UiStatePanel,
} from "@fantappero/ui";
import { useCallback, useEffect, useState } from "react";
import { fetchMyLeagues } from "../api/leagues";
import { getApiErrorMessage, useAuth } from "../auth/AuthContext";
import { loadStoredSession } from "../auth/sessionStorage";
import { Link, useLocation } from "../router/simpleRouter";
import { parseWireframeStateFromSearch } from "../wireframes/useWireframeState";

const DEMO_LEAGUES: LeagueSummary[] = [
  { id: "demo-league-1", name: "Lega Demo", role: "league_admin" },
];

function leagueStateLabel(state: string | undefined): string {
  if (state === "draft") {
    return "Bozza";
  }
  if (state === "active") {
    return "Attiva";
  }
  return "—";
}

/** Elenco leghe dell'utente con stato vuoto e azione di creazione (EP03-01). */
export function LeaguesPage() {
  const { isDemoMode } = useAuth();
  const { search } = useLocation();
  const demoState = isDemoMode ? parseWireframeStateFromSearch(search) : null;
  const [leagues, setLeagues] = useState<LeagueSummary[]>(() =>
    isDemoMode && demoState !== "empty" ? DEMO_LEAGUES : [],
  );
  const [loading, setLoading] = useState(() =>
    isDemoMode ? demoState === "loading" : true,
  );
  const [loadError, setLoadError] = useState<string | null>(() =>
    isDemoMode && demoState === "error" ? "Impossibile caricare le leghe (demo)." : null,
  );

  const loadLeagues = useCallback(async () => {
    if (isDemoMode) {
      if (demoState === "loading") {
        setLoading(true);
        setLoadError(null);
        setLeagues([]);
        return;
      }
      if (demoState === "error") {
        setLoading(false);
        setLoadError("Impossibile caricare le leghe (demo).");
        setLeagues([]);
        return;
      }
      if (demoState === "empty") {
        setLoading(false);
        setLoadError(null);
        setLeagues([]);
        return;
      }
      setLeagues(DEMO_LEAGUES);
      setLoading(false);
      return;
    }

    const stored = loadStoredSession();
    if (!stored?.accessToken) {
      setLoadError("Sessione non disponibile. Accedi di nuovo.");
      setLoading(false);
      return;
    }

    setLoading(true);
    setLoadError(null);
    try {
      const rows = await fetchMyLeagues(stored.accessToken);
      setLeagues(rows);
    } catch (error) {
      setLoadError(getApiErrorMessage(error, "Impossibile caricare le leghe."));
    } finally {
      setLoading(false);
    }
  }, [demoState, isDemoMode]);

  useEffect(() => {
    void loadLeagues();
  }, [loadLeagues]);

  return (
    <PageContainer
      title="Le tue leghe"
      header={<Breadcrumb items={[{ label: "Leghe" }]} />}
    >
      {loading ? (
        <UiStatePanel
          state="loading"
          title="Caricamento leghe"
          message="Recupero delle leghe in corso…"
          testId="leagues-loading"
        />
      ) : null}

      {!loading && loadError ? (
        <UiStatePanel
          state="error"
          title="Errore di caricamento"
          message={loadError}
          testId="leagues-error"
        />
      ) : null}

      {!loading && !loadError && leagues.length === 0 ? (
        <UiStatePanel
          state="empty"
          title="Nessuna lega"
          message="Non partecipi ancora a nessuna lega privata. Creane una per iniziare la configurazione."
          testId="leagues-empty"
        />
      ) : null}

      {!loading && !loadError && leagues.length > 0 ? (
        <section data-testid="leagues-list">
          <ul className="fa-league-list">
            {leagues.map((league) => (
              <li key={league.id} className="fa-league-list__item">
                <Card>
                  <CardHeader>{league.name}</CardHeader>
                  <CardBody>
                    <p>
                      Ruolo:{" "}
                      {league.role === "league_admin" ? "Amministratore" : "Partecipante"}
                    </p>
                    <p>Stato: {leagueStateLabel(undefined)}</p>
                    {league.role === "league_admin" ? (
                      <Link to={`/lega/amministrazione?leagueId=${league.id}`}>
                        <Button
                          variant="ghost"
                          data-testid={`league-admin-link-${league.id}`}
                          style={{ marginTop: "0.5rem" }}
                        >
                          Amministrazione lega
                        </Button>
                      </Link>
                    ) : null}
                  </CardBody>
                </Card>
              </li>
            ))}
          </ul>
        </section>
      ) : null}

      <div className="fa-ds-showcase__row" style={{ marginTop: "1rem" }}>
        <Link to="/leghe/crea">
          <Button variant="secondary" data-testid="leagues-create-link">
            Crea lega
          </Button>
        </Link>
        {!loading && loadError ? (
          <Button variant="ghost" onClick={() => void loadLeagues()} data-testid="leagues-retry">
            Ricarica
          </Button>
        ) : null}
      </div>
    </PageContainer>
  );
}

import type { H2HCalendar, H2HCalendarMatchup, H2HCalendarRound } from "@fantappero/contracts";
import {
  H2H_GOALS_LABEL,
  H2H_POINTS_LABEL,
  describeH2HResult,
  h2hResultAriaLabel,
} from "@fantappero/contracts";
import {
  Badge,
  Button,
  MatchCard,
  Select,
  UiStatePanel,
} from "@fantappero/ui";
import { useEffect, useMemo, useState } from "react";
import { Link } from "../router/simpleRouter";

type Props = {
  calendar: H2HCalendar | null;
  loading: boolean;
  error: string | null;
  liveDegraded: boolean;
  canAdmin: boolean;
  onRetry: () => void;
};

const KICKOFF_FORMATTER = new Intl.DateTimeFormat("it-IT", {
  dateStyle: "short",
  timeStyle: "short",
});

/** Riga temporale della card: quando il risultato è stato calcolato. */
function computedAtLabel(computedAt: string | null | undefined): string {
  if (!computedAt) {
    return "Risultato non ancora calcolato";
  }
  const parsed = new Date(computedAt);
  if (Number.isNaN(parsed.getTime())) {
    return "Risultato non ancora calcolato";
  }
  return `Calcolato il ${KICKOFF_FORMATTER.format(parsed)}`;
}

/** Prima giornata non ancora conclusa; se tutte finite, l'ultima. */
export function resolveDefaultH2HRound(calendar: H2HCalendar): number {
  for (const round of calendar.rounds) {
    if (round.beforeLeagueCreation || round.homologationStatus === "homologated") {
      continue;
    }
    const played = round.matchups.filter((matchup) => !matchup.isBye);
    const allFinal =
      played.length > 0 && played.every((matchup) => matchup.result?.resultFinal === true);
    if (!allFinal) {
      return round.roundNumber;
    }
  }
  const last = calendar.rounds[calendar.rounds.length - 1];
  return last?.roundNumber ?? 1;
}

function roundStatusHint(round: H2HCalendarRound): string {
  if (round.beforeLeagueCreation) {
    return "Lega creata dopo questo turno";
  }
  if (round.homologationStatus === "homologated") {
    return "Risultati finali (storico)";
  }
  const played = round.matchups.filter((matchup) => !matchup.isBye);
  if (played.some((matchup) => matchup.live)) {
    return "LIVE / risultati provvisori";
  }
  const hasResult = played.some((matchup) => matchup.result != null);
  if (hasResult) {
    return "Risultati provvisori / in attesa";
  }
  if (round.europeanTurnStatus) {
    return `Turno europeo: ${round.europeanTurnStatus}`;
  }
  return "Giornata da disputare";
}

function MatchupRow({ matchup }: { matchup: H2HCalendarMatchup }) {
  const homeName = matchup.homeTeamName ?? matchup.homeDisplayName;
  if (matchup.isBye) {
    return (
      <div className="fa-matchday-matchup" data-testid={`h2h-matchup-${matchup.slotId}`}>
        <MatchCard
          homeTeam={homeName}
          awayTeam="Riposo"
          kickoffLabel="Bye"
          status="scheduled"
          statusLabel="Riposo"
          contextLabel="Scontro H2H"
        />
      </div>
    );
  }

  const awayName = matchup.awayTeamName ?? matchup.awayDisplayName ?? "Avversario";
  const display = describeH2HResult(matchup.result);
  const status =
    display.status === "final" ? "finished" : matchup.live ? "live" : "scheduled";
  const statusLabel = matchup.live
    ? "LIVE / provvisorio"
    : display.status === "provisional"
      ? "Provvisorio / in attesa"
      : display.statusLabel;

  return (
    <div className="fa-matchday-matchup" data-testid={`h2h-matchup-${matchup.slotId}`}>
      <Link
        to={`/turni/scontro/${matchup.slotId}`}
        className="fa-matchday-matchup-link"
        data-testid={`h2h-matchup-link-${matchup.slotId}`}
        aria-label={h2hResultAriaLabel(display, homeName, awayName)}
      >
        <MatchCard
          homeTeam={homeName}
          awayTeam={awayName}
          kickoffLabel={computedAtLabel(matchup.result?.computedAt)}
          status={status}
          statusLabel={statusLabel}
          contextLabel="Scontro H2H"
          score={
            display.goalsAvailable && matchup.result
              ? {
                  home: matchup.result.homeFantasyGoals as number,
                  away: matchup.result.awayFantasyGoals as number,
                }
              : null
          }
        />
        <H2HScoreLines display={display} slotId={matchup.slotId} />
      </Link>
    </div>
  );
}

/**
 * Le due grandezze nominate esplicitamente (EP13-P02): il numero grande della
 * MatchCard sono i Gol fantasy, ma da solo resta anonimo.
 */
function H2HScoreLines({
  display,
  slotId,
}: {
  display: ReturnType<typeof describeH2HResult>;
  slotId: string;
}) {
  return (
    <>
      <dl className="fa-h2h-score" data-testid={`h2h-score-${slotId}`}>
        <div className="fa-h2h-score__row">
          <dt className="fa-h2h-score__term">{H2H_GOALS_LABEL}</dt>
          <dd className="fa-h2h-score__value" data-testid={`h2h-score-goals-${slotId}`}>
            {display.goalsLine}
          </dd>
        </div>
        <div className="fa-h2h-score__row">
          <dt className="fa-h2h-score__term">{H2H_POINTS_LABEL}</dt>
          <dd className="fa-h2h-score__value" data-testid={`h2h-score-points-${slotId}`}>
            {display.pointsLine}
          </dd>
        </div>
      </dl>
      {display.unavailableHint ? (
        <p className="fa-h2h-score__hint" data-testid={`h2h-score-hint-${slotId}`}>
          {display.unavailableHint}
        </p>
      ) : null}
    </>
  );
}

/** Tab Calendario fantallenatori — una giornata alla volta via tendina. */
export function MatchdayH2HPanel({
  calendar,
  loading,
  error,
  liveDegraded,
  canAdmin,
  onRetry,
}: Props) {
  const [selectedRound, setSelectedRound] = useState<number | null>(() =>
    calendar ? resolveDefaultH2HRound(calendar) : null,
  );

  useEffect(() => {
    if (!calendar || calendar.rounds.length === 0) {
      setSelectedRound(null);
      return;
    }
    setSelectedRound((current) => {
      if (current != null && calendar.rounds.some((round) => round.roundNumber === current)) {
        return current;
      }
      return resolveDefaultH2HRound(calendar);
    });
  }, [calendar]);

  const activeRoundNumber = selectedRound ?? (calendar ? resolveDefaultH2HRound(calendar) : null);

  const activeRound = useMemo(() => {
    if (!calendar || activeRoundNumber == null) {
      return null;
    }
    return calendar.rounds.find((round) => round.roundNumber === activeRoundNumber) ?? null;
  }, [calendar, activeRoundNumber]);

  if (loading) {
    return (
      <UiStatePanel
        state="loading"
        title="Caricamento calendario"
        message="Recupero degli scontri tra fantallenatori…"
        testId="h2h-loading"
      />
    );
  }

  if (error) {
    return (
      <div data-testid="h2h-error-wrap">
        <UiStatePanel
          state="error"
          title="Calendario non disponibile"
          message={error}
          testId="h2h-error"
        />
        <Button type="button" variant="secondary" onClick={onRetry}>
          Ricarica
        </Button>
      </div>
    );
  }

  if (!calendar) {
    return (
      <div data-testid="h2h-empty-wrap">
        <UiStatePanel
          state="empty"
          title="Calendario non ancora confermato"
          message={
            canAdmin
              ? "Genera e conferma il calendario scontri diretti in Amministrazione lega."
              : "L'amministratore deve generare e confermare il calendario H2H prima che compaia qui."
          }
          testId="h2h-empty"
        />
        {canAdmin ? (
          <Link to="/lega/amministrazione" data-testid="h2h-admin-link">
            Vai ad Amministrazione lega
          </Link>
        ) : null}
      </div>
    );
  }

  const roundOptions = calendar.rounds.map((round) => {
    if (round.beforeLeagueCreation) {
      return {
        value: String(round.roundNumber),
        label: `Giornata ${round.roundNumber} · lega creata dopo`,
      };
    }
    const played = round.matchups.filter((matchup) => !matchup.isBye);
    const finals = played.filter((matchup) => matchup.result?.resultFinal).length;
    const suffix =
      round.homologationStatus === "homologated"
        ? " · storico"
        : finals > 0
          ? ` · ${finals}/${played.length} finali`
          : "";
    return {
      value: String(round.roundNumber),
      label: `Giornata ${round.roundNumber}${suffix}`,
    };
  });

  return (
    <div className="fa-matchday-h2h" data-testid="h2h-calendar">
      <header className="fa-matchday-toolbar">
        <div className="fa-matchday-toolbar__meta">
          <p className="fa-matchday-lede">
            {calendar.roundCount} giornate · {calendar.matchupCount} scontri
            {calendar.byeCount > 0 ? ` · ${calendar.byeCount} riposi` : ""}
          </p>
          <p className="fa-matchday-hint">
            Seleziona una giornata per vedere gli scontri. Le giornate già concluse restano
            disponibili come storico.
          </p>
        </div>
        <Select
          label="Giornata"
          options={roundOptions}
          value={activeRoundNumber != null ? String(activeRoundNumber) : ""}
          onChange={(event) => setSelectedRound(Number(event.target.value))}
          data-testid="h2h-round-select"
        />
        <div className="fa-matchday-toolbar__badges">
          {calendar.live ? (
            <Badge variant="warning" data-testid="h2h-live-badge">
              Aggiornamento live
            </Badge>
          ) : null}
          {liveDegraded ? (
            <span data-testid="h2h-live-degraded" className="fa-matchday-degraded">
              Aggiornamento live rallentato…
            </span>
          ) : null}
        </div>
      </header>

      {activeRound ? (
        <section
          className="fa-matchday-round"
          data-testid={`h2h-round-${activeRound.roundNumber}`}
          aria-labelledby="h2h-round-title"
        >
          <div className="fa-matchday-round__header">
            <h2 id="h2h-round-title">Giornata {activeRound.roundNumber}</h2>
            <Badge
              variant={
                activeRound.homologationStatus === "homologated" ? "success" : "warning"
              }
              data-testid="h2h-round-status"
            >
              {roundStatusHint(activeRound)}
            </Badge>
          </div>
          {activeRound.beforeLeagueCreation ? (
            <UiStatePanel
              state="empty"
              title="Lega creata dopo questo turno"
              message="Questo turno europeo è già trascorso al momento della creazione della lega: non ospita scontri fantasy."
              testId="h2h-round-before-creation"
            />
          ) : (
            <div className="fa-matchday-matchups">
              {activeRound.matchups.map((matchup) => (
                <MatchupRow key={matchup.slotId} matchup={matchup} />
              ))}
            </div>
          )}
        </section>
      ) : null}
    </div>
  );
}

