from __future__ import annotations

from uuid import UUID

from sqlalchemy import select
from sqlalchemy.orm import Session, joinedload

from auth.models.user import User
from authorization.context import LeagueAccess
from authorization.exceptions import LeagueAccessDeniedError, LeagueNotFoundError
from database.enums import PlatformRole
from leagues.models.league import League
from leagues.models.league_membership import LeagueMembership
from observability.metrics import get_metrics


class AuthorizationService:
    """Resolve tenant membership and enforce league boundaries."""

    def __init__(self, session: Session) -> None:
        self._session = session

    def get_league(self, league_id: UUID) -> League | None:
        return self._session.get(League, league_id)

    def get_membership(self, *, user_id: UUID, league_id: UUID) -> LeagueMembership | None:
        stmt = select(LeagueMembership).where(
            LeagueMembership.user_id == user_id,
            LeagueMembership.league_id == league_id,
        )
        return self._session.scalars(stmt).first()

    def list_memberships_for_user(self, user_id: UUID) -> list[LeagueMembership]:
        stmt = (
            select(LeagueMembership)
            .where(LeagueMembership.user_id == user_id)
            .options(joinedload(LeagueMembership.league))
            .order_by(LeagueMembership.created_at.asc())
        )
        return list(self._session.scalars(stmt).unique().all())

    def resolve_league_access(self, user: User, league_id: UUID) -> LeagueAccess:
        league = self.get_league(league_id)
        if league is None:
            get_metrics().incr(
                "authorization_denied_total",
                labels={"reason": "league_not_found"},
            )
            raise LeagueNotFoundError()

        membership = self.get_membership(user_id=user.id, league_id=league_id)
        if membership is not None:
            return LeagueAccess(league=league, user=user, membership_role=membership.role)

        if user.platform_role == PlatformRole.OPERATOR:
            return LeagueAccess(
                league=league,
                user=user,
                membership_role=None,
                operator_bypass=True,
            )

        get_metrics().incr(
            "authorization_denied_total",
            labels={"reason": "league_access_denied"},
        )
        raise LeagueAccessDeniedError()

"""Resolve roster roles/competitions and sync composition status (EP05-05)."""

from __future__ import annotations

from dataclasses import dataclass
from datetime import UTC, datetime
from uuid import UUID

from sqlalchemy import select
from sqlalchemy.orm import Session

from database.enums import FantasyRole, LeagueState, RosterCompositionStatus
from fantasy_teams.composition import (
    RosterCompositionLimits,
    RosterCompositionReport,
    evaluate_roster_composition,
    limits_from_rules,
    would_exceed_role_quota,
)
from fantasy_teams.models import FantasyRosterSlot, FantasyTeam
from leagues.models.league import League
from leagues.models.league_competition import LeagueCompetition
from leagues.models.league_membership import LeagueMembership
from leagues.models.league_rules import LeagueRules
from leagues.validators import LifecycleBlocker
from sports_data.catalog.models import CompetitionSeasonClub, SportSeason
from sports_data.listone.generate import get_role_assignment, list_role_assignments
from sports_data.listone.models import LeagueRoleOverride
from sports_data.listone.overrides import effective_role_for_athlete, get_active_override


@dataclass(frozen=True)
class EffectiveAthleteRole:
    role: FantasyRole
    club_id: UUID | None


def resolve_effective_athlete_roles(
    session: Session,
    *,
    league_id: UUID,
    athlete_ids: list[UUID],
    season_year: int,
    current_round: int = 0,
    competition_ids: set[UUID] | None = None,
) -> dict[UUID, EffectiveAthleteRole]:
    """Resolve listone assignments and league overrides in two bulk queries."""
    unique_ids = list(dict.fromkeys(athlete_ids))
    if not unique_ids:
        return {}
    assignments = list_role_assignments(
        session,
        season_year=season_year,
        athlete_ids=unique_ids,
        competition_ids=competition_ids,
    )
    overrides = session.scalars(
        select(LeagueRoleOverride).where(
            LeagueRoleOverride.league_id == league_id,
            LeagueRoleOverride.athlete_id.in_(unique_ids),
            LeagueRoleOverride.superseded_at.is_(None),
        )
    ).all()
    overrides_by_athlete = {row.athlete_id: row for row in overrides}
    return {
        assignment.athlete_id: EffectiveAthleteRole(
            role=effective_role_for_athlete(
                official_role=assignment.role,
                override=overrides_by_athlete.get(assignment.athlete_id),
                current_round=current_round,
            ),
            club_id=assignment.club_id,
        )
        for assignment in assignments
    }


def resolve_league_rules_limits(session: Session, league_id: UUID) -> RosterCompositionLimits:
    rules = session.scalar(select(LeagueRules).where(LeagueRules.league_id == league_id))
    if rules is None:
        return limits_from_rules(
            roster_size=35,
            goalkeepers=3,
            defenders=11,
            midfielders=11,
            forwards=10,
        )
    return limits_from_rules(
        roster_size=rules.roster_size,
        goalkeepers=rules.goalkeepers,
        defenders=rules.defenders,
        midfielders=rules.midfielders,
        forwards=rules.forwards,
    )


def league_requires_complete_rosters(league: League) -> bool:
    """Incomplete rosters are allowed only before season start (during auction)."""
    return league.state not in {LeagueState.DRAFT, LeagueState.CONFIGURING, LeagueState.AUCTION}


def resolve_effective_athlete_role(
    session: Session,
    *,
    league_id: UUID,
    athlete_id: UUID,
    season_year: int,
    current_round: int = 0,
    competition_ids: set[UUID] | None = None,
) -> FantasyRole | None:
    assignment = get_role_assignment(
        session,
        athlete_id=athlete_id,
        season_year=season_year,
        competition_ids=competition_ids,
    )
    if assignment is None:
        return None
    override = get_active_override(session, league_id=league_id, athlete_id=athlete_id)
    return effective_role_for_athlete(
        official_role=assignment.role,
        override=override,
        current_round=current_round,
    )


def resolve_club_competition_ids(
    session: Session,
    *,
    club_ids: set[UUID],
    season_year: int,
    league_competition_ids: set[UUID],
) -> dict[UUID, set[UUID]]:
    """Map club → competition ids intersecting the league catalog for the season year."""
    if not club_ids or not league_competition_ids:
        return {}
    rows = session.execute(
        select(CompetitionSeasonClub.club_id, SportSeason.competition_id)
        .join(SportSeason, SportSeason.id == CompetitionSeasonClub.sport_season_id)
        .where(
            CompetitionSeasonClub.club_id.in_(club_ids),
            SportSeason.year == season_year,
            SportSeason.competition_id.in_(league_competition_ids),
        )
    ).all()
    mapping: dict[UUID, set[UUID]] = {}
    for club_id, competition_id in rows:
        mapping.setdefault(club_id, set()).add(competition_id)
    return mapping


def evaluate_team_composition(
    session: Session,
    team: FantasyTeam,
    *,
    league: League,
    require_complete: bool | None = None,
    effective_roles: dict[UUID, EffectiveAthleteRole] | None = None,
) -> RosterCompositionReport:
    limits = resolve_league_rules_limits(session, league.id)
    must_complete = (
        league_requires_complete_rosters(league) if require_complete is None else require_complete
    )
    league_competition_ids = {
        row.competition_id
        for row in session.scalars(
            select(LeagueCompetition).where(LeagueCompetition.league_id == league.id)
        ).all()
    }

    slots = list(
        session.scalars(
            select(FantasyRosterSlot)
            .where(FantasyRosterSlot.fantasy_team_id == team.id)
            .order_by(FantasyRosterSlot.slot_index.asc())
        ).all()
    )

    athlete_ids = [slot.athlete_id for slot in slots if slot.athlete_id is not None]
    resolved = effective_roles
    if resolved is None:
        resolved = resolve_effective_athlete_roles(
            session,
            league_id=league.id,
            athlete_ids=athlete_ids,
            season_year=league.season_year,
        )
    roles = [resolved[athlete_id].role for athlete_id in athlete_ids if athlete_id in resolved]
    unresolved = len(athlete_ids) - len(roles)
    club_ids = {
        item.club_id
        for athlete_id, item in resolved.items()
        if athlete_id in athlete_ids and item.club_id is not None
    }

    club_competitions = resolve_club_competition_ids(
        session,
        club_ids=club_ids,
        season_year=league.season_year,
        league_competition_ids=league_competition_ids,
    )
    competition_ids: set[UUID] = set()
    for comps in club_competitions.values():
        competition_ids.update(comps)

    return evaluate_roster_composition(
        limits=limits,
        roles=roles,
        competition_ids=competition_ids,
        require_complete=must_complete,
        unresolved_role_count=unresolved,
    )


def sync_team_composition_status(
    session: Session,
    team: FantasyTeam,
    *,
    league: League,
    require_complete: bool | None = None,
) -> RosterCompositionReport:
    report = evaluate_team_composition(
        session,
        team,
        league=league,
        require_complete=require_complete,
    )
    previous = team.composition_status
    team.composition_status = report.status
    if report.status == RosterCompositionStatus.VALIDATED:
        if team.validated_at is None or previous != RosterCompositionStatus.VALIDATED:
            team.validated_at = datetime.now(UTC)
    else:
        team.validated_at = None
    return report


def assert_assignment_respects_role_quota(
    session: Session,
    *,
    league: League,
    team: FantasyTeam,
    athlete_id: UUID,
    slot_index: int,
) -> FantasyRole:
    """Reject assignments that would exceed configurable role limits."""
    from auth.exceptions import ValidationAuthError
    from fantasy_teams.composition import ROLE_LABEL_IT

    limits = resolve_league_rules_limits(session, league.id)
    new_role = resolve_effective_athlete_role(
        session,
        league_id=league.id,
        athlete_id=athlete_id,
        season_year=league.season_year,
        competition_ids={competition.id for competition in league.competitions},
    )
    if new_role is None:
        raise ValidationAuthError(
            "Il calciatore non ha un ruolo listone valido (P–D–C–A).",
            code="role_unresolved",
        )

    slots = list(
        session.scalars(
            select(FantasyRosterSlot).where(FantasyRosterSlot.fantasy_team_id == team.id)
        ).all()
    )
    current_roles: list[FantasyRole | None] = []
    replacing: FantasyRole | None = None
    for slot in slots:
        if slot.athlete_id is None:
            continue
        role = resolve_effective_athlete_role(
            session,
            league_id=league.id,
            athlete_id=slot.athlete_id,
            season_year=league.season_year,
        )
        if slot.slot_index == slot_index:
            replacing = role
            continue
        current_roles.append(role)

    if would_exceed_role_quota(
        limits=limits,
        current_roles=current_roles,
        new_role=new_role,
        replacing_role=replacing,
    ):
        limit = limits.for_role(new_role)
        raise ValidationAuthError(
            f"Limite {ROLE_LABEL_IT[new_role]} raggiunto ({limit}).",
            code="role_quota_exceeded",
        )
    return new_role


def activation_roster_and_credit_blockers(
    session: Session,
    league: League,
) -> list[LifecycleBlocker]:
    """Real season-start blockers replacing EP03-05 placeholders (EP05-05)."""
    from sqlalchemy.orm import selectinload

    from fantasy_teams.ledger import find_account_for_team

    blockers: list[LifecycleBlocker] = []
    memberships = list(
        session.scalars(
            select(LeagueMembership).where(LeagueMembership.league_id == league.id)
        ).all()
    )
    teams = {
        team.membership_id: team
        for team in session.scalars(
            select(FantasyTeam)
            .where(FantasyTeam.league_id == league.id)
            .options(
                selectinload(FantasyTeam.slots),
                selectinload(FantasyTeam.credit_account),
            )
        ).all()
    }

    missing_teams = 0
    invalid_rosters = 0
    missing_credits = 0
    for membership in memberships:
        team = teams.get(membership.id)
        if team is None:
            missing_teams += 1
            continue
        report = evaluate_team_composition(
            session,
            team,
            league=league,
            require_complete=True,
        )
        if not report.is_valid_for_season_start:
            invalid_rosters += 1
        account = team.credit_account or find_account_for_team(session, team.id)
        if account is None or account.balance < 0:
            missing_credits += 1

    if missing_teams or invalid_rosters:
        detail_parts: list[str] = []
        if missing_teams:
            detail_parts.append(f"{missing_teams} squadre mancanti")
        if invalid_rosters:
            detail_parts.append(f"{invalid_rosters} rose non valide o incomplete")
        blockers.append(
            LifecycleBlocker(
                code="fantasy_teams_not_configured",
                message=(
                    "Completa squadre e rose prima di avviare la stagione "
                    f"({'; '.join(detail_parts)})."
                ),
                action_hint="teams",
            )
        )
    if missing_credits:
        blockers.append(
            LifecycleBlocker(
                code="credits_not_configured",
                message=(
                    "Verifica i crediti di tutte le squadre prima di avviare la stagione "
                    f"({missing_credits} conti assenti o non validi)."
                ),
                action_hint="teams",
            )
        )
    return blockers


def league_rosters_complete(session: Session, league: League) -> bool:
    """True se ogni membership ha una squadra con rosa completa e valida.

    Stesso controllo di composizione usato per sbloccare l'avvio stagione
    (`activation_roster_and_credit_blockers`), ma senza il vincolo sui
    crediti: qui serve solo sapere se le rose sono pronte per generare il
    calendario H2H (EP13-P04) — le rose si possono completare anche senza
    passare per lo stato "asta" (es. assegnazione manuale/random IA in
    Amministrazione lega), quindi il prerequisito è sulle rose stesse, non
    sullo stato macro della lega.
    """
    memberships = list(
        session.scalars(
            select(LeagueMembership).where(LeagueMembership.league_id == league.id)
        ).all()
    )
    if not memberships:
        return False
    teams = {
        team.membership_id: team
        for team in session.scalars(
            select(FantasyTeam).where(FantasyTeam.league_id == league.id)
        ).all()
    }
    for membership in memberships:
        team = teams.get(membership.id)
        if team is None:
            return False
        report = evaluate_team_composition(session, team, league=league, require_complete=True)
        if not report.is_valid_for_season_start:
            return False
    return True

"""Celery tasks for automatic european turn generation."""
from __future__ import annotations
import database.models # noqa: F401 — register ORM mappers from app.worker import celery_app from auth.exceptions import ValidationAuthError from config.settings.loader import get_api_settings, validate_worker_settings from database.session import create_engine_from_url, create_session_factory, session_scope from fantasy_turns.calendar_refresh_progress import CalendarRefreshProgress, save_progress from fantasy_turns.service import FantasyTurnService from leagues.models.league import League from observability.logging import get_logger from sports_data.provider.errors import ProviderAuthError, ProviderError, ProviderRateLimitError
logger = get_logger(__name__)
@celery_app.task(name="fantasy_turns.ensure_upcoming") def ensure_upcoming_fantasy_turns_task() -> dict[str, int]: """Materialize upcoming weekend/midweek turns for all ACTIVE leagues.""" try: worker = validate_worker_settings() horizon = worker.fantasy_turns_horizon_days enabled = worker.fantasy_turns_auto_generate_enabled except Exception: api = get_api_settings() horizon = api.fantasy_turns_horizon_days enabled = api.fantasy_turns_auto_generate_enabled
if not enabled: logger.info("fantasy_turns_ensure_skipped_disabled") return { "leagues": 0, "created": 0, "opened": 0, "upgraded": 0, "duplicates": 0, "waiting": 0, }
settings = get_api_settings() engine = create_engine_from_url(settings.database_url) factory = create_session_factory(engine) try: with session_scope(factory) as session: totals = FantasyTurnService(session).ensure_upcoming_for_active_leagues( horizon_days=horizon, auto_open=True, ) finally: engine.dispose() logger.info("fantasy_turns_ensure_task_done", extra=totals) return totals
@celery_app.task(name="fantasy_turns.refresh_full_calendar_active_leagues") def refresh_full_calendar_active_leagues_task() -> dict[str, int]: """Giro periodico automatico di "Aggiorna calendario" per tutte le leghe attive.
Copre l'intera stagione (non solo l'orizzonte di `ensure_upcoming`), così una fixture "da aggiornare" che riceve una data lontana nel tempo entra comunque in un turno senza che l'admin debba premere il pulsante. Il pulsante resta disponibile per un aggiornamento immediato su richiesta. """ try: worker = validate_worker_settings() enabled = worker.fantasy_turns_full_refresh_enabled except Exception: api = get_api_settings() enabled = api.fantasy_turns_full_refresh_enabled
if not enabled: logger.info("fantasy_calendar_refresh_periodic_skipped_disabled") return {"leagues": 0, "refreshed": 0, "failed": 0}
settings = get_api_settings() engine = create_engine_from_url(settings.database_url) factory = create_session_factory(engine) try: with session_scope(factory) as session: totals = FantasyTurnService(session).refresh_full_calendar_for_active_leagues() finally: engine.dispose() return totals
@celery_app.task(name="fantasy_turns.refresh_full_calendar_active_leagues_now") def refresh_full_calendar_active_leagues_now_task(*, job_id: str, actor_id: str | None) -> dict: """Azione massiva dell'operatore: "Aggiorna calendario" per tutte le leghe attive, on-demand invece che al prossimo giro del cron 6h.
Stesso corpo del cron periodico (`refresh_full_calendar_active_leagues_task`) — isola già i fallimenti per lega — solo tracciato come job con progress perché può iterare molte leghe e ognuna chiama il provider esterno. """ settings = get_api_settings() engine = create_engine_from_url(settings.database_url) factory = create_session_factory(engine)
PLATFORM_SCOPE = "platform" try: save_progress( CalendarRefreshProgress( job_id=job_id, league_id=PLATFORM_SCOPE, status="running", percent=1, stage="running", message="Aggiornamento calendario avviato per tutte le leghe attive…", ) ) with session_scope(factory) as session: totals = FantasyTurnService(session).refresh_full_calendar_for_active_leagues() message = ( f"Leghe attive: {totals['leagues']}, aggiornate: {totals['refreshed']}, " f"fallite: {totals['failed']}. Fixture nuove: {totals['fixturesCreated']}, " f"aggiornate: {totals['fixturesUpdated']}." ) save_progress( CalendarRefreshProgress( job_id=job_id, league_id=PLATFORM_SCOPE, status="completed", percent=100, stage="completed", message=message, result=totals, ) ) return {"status": "completed", "job_id": job_id, "actor_id": actor_id} except Exception: save_progress( CalendarRefreshProgress( job_id=job_id, league_id=PLATFORM_SCOPE, status="failed", percent=0, stage="failed", message="Aggiornamento calendario massivo non riuscito.", error_code="calendar_refresh_failed", ) ) raise finally: engine.dispose()
@celery_app.task(name="fantasy_turns.refresh_full_calendar_from_provider") def refresh_full_calendar_task(*, job_id: str, league_id: str, actor_id: str | None) -> dict: """Comando admin "Aggiorna calendario": sync provider + backfill stagionale.""" from uuid import UUID
settings = get_api_settings() engine = create_engine_from_url(settings.database_url) factory = create_session_factory(engine)
def publish(percent: int, stage: str, message: str, *, status: str = "running") -> None: save_progress( CalendarRefreshProgress( job_id=job_id, league_id=league_id, status=status, percent=percent, stage=stage, message=message, ) )
try: publish(1, "running", "Aggiornamento calendario avviato…") with session_scope(factory) as session: league = session.get(League, UUID(league_id)) if league is None: save_progress( CalendarRefreshProgress( job_id=job_id, league_id=league_id, status="failed", percent=0, stage="failed", message="Lega non trovata.", error_code="league_not_found", ) ) return {"status": "failed", "code": "league_not_found"} result = FantasyTurnService(session).refresh_full_calendar( league, actor_id=UUID(actor_id) if actor_id else None, on_progress=lambda percent, stage, message: publish(percent, stage, message), ) save_progress( CalendarRefreshProgress( job_id=job_id, league_id=league_id, status="completed", percent=100, stage="completed", message=result.message, result=result.model_dump(by_alias=True, mode="json"), ) ) return {"status": "completed", "job_id": job_id} except ValidationAuthError as exc: save_progress( CalendarRefreshProgress( job_id=job_id, league_id=league_id, status="failed", percent=0, stage="failed", message=exc.message, error_code=exc.code, ) ) return {"status": "failed", "code": exc.code} except ProviderRateLimitError: save_progress( CalendarRefreshProgress( job_id=job_id, league_id=league_id, status="failed", percent=0, stage="failed", message="Quota API-Football esaurita o rate limit attivo. Riprova tra poco.", error_code="provider_rate_limited", ) ) return {"status": "failed", "code": "provider_rate_limited"} except ProviderAuthError: save_progress( CalendarRefreshProgress( job_id=job_id, league_id=league_id, status="failed", percent=0, stage="failed", message="Autenticazione provider rifiutata. Verifica API_FOOTBALL_KEY.", error_code="provider_auth_failed", ) ) return {"status": "failed", "code": "provider_auth_failed"} except ProviderError: save_progress( CalendarRefreshProgress( job_id=job_id, league_id=league_id, status="failed", percent=0, stage="failed", message="Aggiornamento calendario non riuscito dal provider sportivo.", error_code="provider_sync_failed", ) ) return {"status": "failed", "code": "provider_sync_failed"} except Exception: save_progress( CalendarRefreshProgress( job_id=job_id, league_id=league_id, status="failed", percent=0, stage="failed", message="Aggiornamento calendario non riuscito.", error_code="calendar_refresh_failed", ) ) raise finally: engine.dispose()
@celery_app.task(name="fantasy_turns.repair_historical_rounds") def repair_historical_rounds_task(*, job_id: str, actor_id: str | None, reason: str) -> dict: """Azione massiva dell'operatore: "Ricalcola storico" (EP-turni-calcolo).
Riapre (se serve, con motivo obbligatorio) e ricalcola i turni con un buco storico — formazioni mai risolte, scontri H2H mai chiusi — con lo stesso motore usato dal job automatico e dai comandi puntuali. Tracciato come job con progress: può iterare molti turni di molte leghe. """ from uuid import UUID
from fantasy_turns.round_calculation_progress import RoundRepairProgress from fantasy_turns.round_calculation_progress import save_progress as save_repair_progress from fantasy_turns.round_repair_service import repair_historical_rounds_for_active_leagues
PLATFORM_SCOPE = "platform" settings = get_api_settings() engine = create_engine_from_url(settings.database_url) factory = create_session_factory(engine) try: save_repair_progress( RoundRepairProgress( job_id=job_id, league_id=PLATFORM_SCOPE, status="running", percent=1, stage="running", message="Ricalcolo storico avviato…", ) ) with session_scope(factory) as session: result = repair_historical_rounds_for_active_leagues( session, actor_id=UUID(actor_id) if actor_id else None, reason=reason, ) message = ( f"Leghe attive: {result.leagues}, turni con un buco storico: " f"{result.rounds_considered}, riparati: {result.rounds_repaired}, " f"falliti: {result.rounds_failed}." ) save_repair_progress( RoundRepairProgress( job_id=job_id, league_id=PLATFORM_SCOPE, status="completed", percent=100, stage="completed", message=message, result=result.as_dict(), ) ) return {"status": "completed", "job_id": job_id, "actor_id": actor_id} except Exception: save_repair_progress( RoundRepairProgress( job_id=job_id, league_id=PLATFORM_SCOPE, status="failed", percent=0, stage="failed", message="Ricalcolo storico non riuscito.", error_code="round_repair_failed", ) ) raise finally: engine.dispose()

"""Celery tasks for automatic european turn generation."""
from __future__ import annotations
