logger = get_logger(__name__)
@celery_app.task(name="fantasy_turns.ensure_upcoming") def ensure_upcoming_fantasy_turns_task() -> dict[str, int]: """Materialize upcoming weekend/midweek turns for all ACTIVE leagues.""" try: worker = validate_worker_settings() horizon = worker.fantasy_turns_horizon_days enabled = worker.fantasy_turns_auto_generate_enabled except Exception: api = get_api_settings() horizon = api.fantasy_turns_horizon_days enabled = api.fantasy_turns_auto_generate_enabled
if not enabled: logger.info("fantasy_turns_ensure_skipped_disabled") return { "leagues": 0, "created": 0, "opened": 0, "upgraded": 0, "duplicates": 0, "waiting": 0, }
