@celery_app.task(name="fantasy_turns.materialize_initial_for_league") def materialize_initial_fantasy_turns_task(*, league_id: str, actor_id: str | None) -> dict[str, int]: """Backfill stagionale post-creazione lega (EP13-P04).
Agganciato alla fine di ``LeagueService.create_league`` invece che eseguito in modo sincrono nella request: sposta all'esterno il costo (potenzialmente decine di finestre da valutare) senza far attendere l'admin che ha appena creato la lega. È un no-op innocuo finché le rose non sono assegnate (nessuna finestra supera la soglia di copertura) — si materializza da sola, con la numerazione cronologica definitiva fin dal primo turno, non appena rose e/o fixture sono pronte. """ try: worker = validate_worker_settings() enabled = worker.fantasy_turns_auto_generate_enabled except Exception: api = get_api_settings() enabled = api.fantasy_turns_auto_generate_enabled
if not enabled: logger.info("fantasy_turns_materialize_initial_skipped_disabled", extra={"league_id": league_id}) return {"created": 0, "upgraded": 0, "opened": 0, "removed": 0}
from uuid import UUID
