import assert from "node:assert/strict";
import { describe, it } from "node:test";
import {
  LEAGUE_LIFECYCLE_PHASES,
  describeLeagueLifecycleStep,
  leagueLifecyclePhaseIndex,
  type LeagueLifecycle,
} from "./leagues.ts";

function lifecycle(overrides: Partial<LeagueLifecycle>): LeagueLifecycle {
  return {
    state: "draft",
    allowedTransitions: [],
    blockers: [],
    ...overrides,
  };
}

describe("leagueLifecyclePhaseIndex", () => {
  it("groups draft and configuring in the same setup phase", () => {
    assert.equal(leagueLifecyclePhaseIndex("draft"), 0);
    assert.equal(leagueLifecyclePhaseIndex("configuring"), 0);
    assert.equal(LEAGUE_LIFECYCLE_PHASES[0]?.key, "setup");
  });

  it("maps auction and the post-season states to their own phases", () => {
    assert.equal(leagueLifecyclePhaseIndex("auction"), 1);
    assert.equal(leagueLifecyclePhaseIndex("active"), 2);
    assert.equal(leagueLifecyclePhaseIndex("concluded"), 2);
    assert.equal(leagueLifecyclePhaseIndex("archived"), 2);
  });
});

describe("describeLeagueLifecycleStep", () => {
  it("exposes a single forward CTA per state, disabled while blocked", () => {
    const blocked = describeLeagueLifecycleStep(
      lifecycle({ state: "configuring", allowedTransitions: [] }),
    );
    assert.equal(blocked.forwardTarget, "auction");
    assert.equal(blocked.forwardLabel, "Avvia l'asta");
    assert.equal(blocked.forwardEnabled, false);

    const unblocked = describeLeagueLifecycleStep(
      lifecycle({ state: "configuring", allowedTransitions: ["auction"] }),
    );
    assert.equal(unblocked.forwardEnabled, true);
  });

  it("only exposes a rollback CTA from auction back to configuring", () => {
    const fromAuction = describeLeagueLifecycleStep(
      lifecycle({ state: "auction", allowedTransitions: ["configuring", "active"] }),
    );
    assert.equal(fromAuction.rollbackTarget, "configuring");
    assert.equal(fromAuction.rollbackLabel, "Torna in configurazione");
    assert.equal(fromAuction.forwardTarget, "active");
    assert.equal(fromAuction.forwardEnabled, true);

    const fromConfiguring = describeLeagueLifecycleStep(
      lifecycle({ state: "configuring", allowedTransitions: ["auction"] }),
    );
    assert.equal(fromConfiguring.rollbackTarget, null);
  });

  it("has no forward CTA once the league is archived", () => {
    const archived = describeLeagueLifecycleStep(
      lifecycle({ state: "archived", allowedTransitions: [] }),
    );
    assert.equal(archived.forwardTarget, null);
    assert.equal(archived.forwardLabel, null);
    assert.equal(archived.forwardEnabled, false);
  });
});

/** League configuration contracts (EP03-01). */

/** Competition available in the MVP catalog. */
export interface CompetitionSummary {
  id: string;
  providerId: number;
  name: string;
  country: string;
}

/** Detailed league view including selected competitions. */
export interface LeagueDetail {
  id: string;
  name: string;
  seasonYear: number;
  state: "draft" | "active";
  viewerRole: "member" | "league_admin" | null;
  competitions: CompetitionSummary[];
}

export interface CreateLeagueRequest {
  name: string;
  seasonYear: number;
  competitionIds: string[];
}

/** League configuration contracts (EP03-02). */

export type LeagueState =
  | "draft"
  | "configuring"
  | "auction"
  | "active"
  | "concluded"
  | "archived";

/**
 * Sezione del pannello amministrazione a cui la UI può rimandare l'admin per
 * risolvere un blocker (EP03-05-UX). Puramente indicativo lato client.
 */
export type LeagueLifecycleActionHint = "rules" | "members" | "calendar" | "teams";

export interface LeagueLifecycleBlocker {
  code: string;
  message: string;
  actionHint?: LeagueLifecycleActionHint | null;
}

export interface LeagueLifecycle {
  state: LeagueState;
  allowedTransitions: LeagueState[];
  blockers: LeagueLifecycleBlocker[];
}

export interface TransitionLeagueStateRequest {
  targetState: LeagueState;
}

/**
 * Percorso "a tappe" mostrato all'admin al posto dei 6 stati grezzi
 * (EP03-05-UX): Bozza e Configurazione sono la stessa fase percepita.
 */
export type LeagueLifecyclePhaseKey = "setup" | "auction" | "season";

export interface LeagueLifecyclePhase {
  key: LeagueLifecyclePhaseKey;
  label: string;
  states: LeagueState[];
}

export const LEAGUE_LIFECYCLE_PHASES: readonly LeagueLifecyclePhase[] = [
  { key: "setup", label: "Impostazione", states: ["draft", "configuring"] },
  { key: "auction", label: "Asta", states: ["auction"] },
  { key: "season", label: "Campionato", states: ["active", "concluded", "archived"] },
];

/** Indice (0-based) della fase corrente nello stepper, -1 se non mappato. */
export function leagueLifecyclePhaseIndex(state: LeagueState): number {
  return LEAGUE_LIFECYCLE_PHASES.findIndex((phase) => phase.states.includes(state));
}

const FORWARD_TARGET: Partial<Record<LeagueState, LeagueState>> = {
  draft: "configuring",
  configuring: "auction",
  auction: "active",
  active: "concluded",
  concluded: "archived",
};

const FORWARD_ACTION_LABEL: Record<LeagueState, string> = {
  draft: "Inizia la configurazione",
  configuring: "Avvia l'asta",
  auction: "Avvia il campionato",
  active: "Concludi la stagione",
  concluded: "Archivia la lega",
  archived: "Lega archiviata",
};

const ROLLBACK_TARGET: Partial<Record<LeagueState, LeagueState>> = {
  auction: "configuring",
};

const ROLLBACK_ACTION_LABEL: Partial<Record<LeagueState, string>> = {
  auction: "Torna in configurazione",
};

/** Un solo passo "in avanti" per volta, invece di un elenco di stati grezzi. */
export interface LeagueLifecycleStep {
  forwardTarget: LeagueState | null;
  forwardLabel: string | null;
  /** True quando nessun blocker impedisce la transizione in avanti. */
  forwardEnabled: boolean;
  rollbackTarget: LeagueState | null;
  rollbackLabel: string | null;
}

export function describeLeagueLifecycleStep(lifecycle: LeagueLifecycle): LeagueLifecycleStep {
  const forwardTarget = FORWARD_TARGET[lifecycle.state] ?? null;
  const rollbackTarget = ROLLBACK_TARGET[lifecycle.state] ?? null;
  return {
    forwardTarget,
    forwardLabel: forwardTarget ? FORWARD_ACTION_LABEL[lifecycle.state] : null,
    forwardEnabled:
      forwardTarget !== null && lifecycle.allowedTransitions.includes(forwardTarget),
    rollbackTarget,
    rollbackLabel: rollbackTarget ? (ROLLBACK_ACTION_LABEL[lifecycle.state] ?? null) : null,
  };
}

/** Etichetta del link "vai a sistemare" mostrato accanto a ogni blocker. */
export const LEAGUE_LIFECYCLE_ACTION_HINT_LABEL: Record<LeagueLifecycleActionHint, string> = {
