export type MarketReleaseReason = "voluntary" | "league_exit";

export type TradeStatus =
  | "proposed"
  | "cancelled"
  | "expired"
  | "accepted"
  | "rejected"
  | "countered"
  | "pending_approval"
  | "executed"
  | "rejected_by_admin";

